Bash(cat > /tmp/test-dashboard.mjs << 'SCRIPT'
import 'dotenv/config';
import pg from 'pg';
const { Pool } = pg;
const pool = new Pool\({ connectionString: process.env.DATABASE_URL }\);

const cutoff = new Date\('2025-12-15'\);

const acts = await pool.query\("SELECT * FROM volunteer_activities WHERE date >= $1", [cutoff]\);
const orgs = await pool.query\('SELECT * FROM organizations'\);
const projects = await pool.query\('SELECT id, organization_id FROM projects'\);

console.log\('Activities:', acts.rows.length, '| Orgs:', orgs.rows.length, '| Projects:', projects.rows.length\);

const projectOrgMap = new Map\(\);
for \(const p of projects.rows\) projectOrgMap.set\(p.id, p.organization_id\);

const orgActivityMap = new Map\(\);
const UNASSIGNED = 0;
for \(const a of acts.rows\) {
  const orgId = \(a.project_id ? projectOrgMap.get\(a.project_id\) : undefined\) ?? UNASSIGNED;
  if \(!orgActivityMap.has\(orgId\)\) orgActivityMap.set\(orgId, { total:0, verified:0, lastVerified:null, pending:0, hours:0 }\);
  const entry = orgActivityMap.get\(orgId\);
  entry.total++;
  if \(a.verification_status === 'approved'\) {
    entry.verified++;
    entry.hours += \(a.hours || 0\);
    if \(a.verified_at && \(!entry.lastVerified || new Date\(a.verified_at\) > entry.lastVerified\)\)
      entry.lastVerified = new Date\(a.verified_at\);
  } else if \(a.verification_status === 'pending'\) entry.pending++;
}
console.log\('OrgActivityMap keys:', Array.from\(orgActivityMap.keys\(\)\)\);

// Recent verifications
const verified = acts.rows.filter\(a => a.verification_status === 'approved'\);
const recent = verified.sort\(\(a,b\) => \(b.verified_at ? new Date\(b.verified_at\).getTime\(\):0\) - \(a.verified_at ? new Date\(a.verified_at\).getTime\(\):0\)\).slice\(0,10\);
console.log\('Recent[0] id:', recent[0]?.id, 'verified_at:', recent[0]?.verified_at\);

const projectIdSet = new Set\(recent.filter\(a => a.project_id\).map\(a => a.project_id\)\);
const projectIds = Array.from\(projectIdSet\);
const pd = projectIds.length > 0 ? await pool.query\('SELECT id, name, organization_id FROM projects WHERE id = ANY\($1\)', [projectIds]\) : {rows:[]};
console.log\('Project details:', pd.rows\);

// Check verifiedWithin72h calculation with null verified_at
const seventyTwoHours = 72 * 60 * 60 * 1000;
const within72h = verified.filter\(a => a.verified_at && a.created_at && \(new Date\(a.verified_at\).getTime\(\) - new Date\(a.created_at\).getTime\(\)\) <= seventyTwoHours\);
console.log\('Within72h:', within72h.length, '/ total verified:', verified.length\);

// CSR partners
const partners = await pool.query\('SELECT * FROM csr_partners'\);
const engagements = await pool.query\('SELECT * FROM employee_engagement'\);
console.log\('Partners:', partners.rows.length, '| Engagements:', engagements.rows.length\);

for \(const p of partners.rows\) {
  const allEng = engagements.rows.filter\(e => e.partner_id === p.id\);
  const completed = allEng.filter\(e => e.completion_status === 'completed'\);
  const countrySet = new Set\(\);
  for \(const e of allEng\) {
    if \(e.project_id\) {
      const proj = projects.rows.find\(pr => pr.id === e.project_id\);
      if \(proj\) {
        const org = orgs.rows.find\(o => o.id === proj.organization_id\);
        if \(org?.country\) countrySet.add\(org.country\);
      }
    }
  }
  const uniqueEmails = new Set\(allEng.map\(e => e.employee_email\)\).size;
  console.log\(`Partner ${p.company_name}: outcomes=${completed.length}, countries=${countrySet.size}, employees=${uniqueEmails}`\);
}

console.log\('ALL CHECKS PASSED'\);
await pool.end\(\);
SCRIPT
node /tmp/test-dashboard.mjs 2>)

